func TestRuleset_Run(t *testing.T) {
	tests := []struct {
		name, data string
	}{
		{
			name: "valid yaml",
			data: `
---
apiVersion: apps/v1
kind: Deployment
spec:
  selector:
    matchLabels:
      app: podinfo
  template:
    metadata:
      annotations:
        prometheus.io/scrape: "true"
      labels:
        app: podinfo
    spec:
      hostNetwork: true
      initContainers:
        - name: init1
          securityContext:
            readOnlyRootFilesystem: true
        - name: init2
          securityContext:
            readOnlyRootFilesystem: false
        - name: init3
      containers:
        - name: c1
        - name: c2
          securityContext:
            readOnlyRootFilesystem: false
            runAsNonRoot: true
            runAsUser: 1001
        - name: c3
          securityContext:
            readOnlyRootFilesystem: true
`,
		},
		{
			name: "valid json",
			data: `
{
  "apiVersion": "apps/v1",
  "kind": "Deployment",
  "spec": {
    "selector": {
      "matchLabels": {
        "app": "podinfo"
      }
    },
    "template": {
      "metadata": {
        "annotations": {
          "prometheus.io/scrape": "true"
        },
        "labels": {
          "app": "podinfo"
        }
      },
      "spec": {
        "hostNetwork": true,
        "initContainers": [
          {
            "name": "init1",
            "securityContext": {
              "readOnlyRootFilesystem": true
            }
          },
          {
            "name": "init2",
            "securityContext": {
              "readOnlyRootFilesystem": false
            }
          },
          {
            "name": "init3"
          }
        ],
        "containers": [
          {
            "name": "c1"
          },
          {
            "name": "c2",
            "securityContext": {
              "readOnlyRootFilesystem": false,
              "runAsNonRoot": true,
              "runAsUser": 1001
            }
          },
          {
            "name": "c3",
            "securityContext": {
              "readOnlyRootFilesystem": true
            }
          }
        ]
      }
    }
  }
}`,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			config := NewDefaultSchemaConfig()
			ruleset, err := NewRuleset(zap.NewNop().Sugar())
			if err != nil {
				t.Fatal(err.Error())
			}
			reports, err := ruleset.Run("kube.yaml", []byte(tt.data), config)
			if err != nil || len(reports) == 0 {
				t.Fatal(err.Error())
			}

			report := reports[0]

			critical := len(report.Scoring.Critical)
			if critical < 1 {
				t.Errorf("Got %v critical rules wanted many", critical)
			}

			advise := len(report.Scoring.Advise)
			if advise < 1 {
				t.Errorf("Got %v advise rules wanted many", advise)
			}

			if report.Score > 0 {
				t.Errorf("Got score %v wanted a negative value", report.Score)
			}

		})
	}
}

